# Write your MySQL query statement below
select round(sum(c.tiv_2016),2) as tiv_2016 from (select * from insurance group by lat,lon having count(*)<2)as a inner JOIN (select * from insurance where (tiv_2015) in(select tiv_2015 from insurance group by tiv_2015 having count(*)>1) ) as c on a.pid=c.pid ;